        if len(arg_annotations) != len(args):
            raise TypeError("The number of arguments does not match the function specification.")

        # Check the types of positional arguments
        for (arg, annotation), value in zip(arg_annotations.items(), args):
            if type(value) is not annotation:
                raise TypeError(f"The argument '{arg}' is not of the expected type {annotation}.")

        # Check the types of keyword arguments
